public sealed record InboundToken(
    string Scheme,
    string? Version,
    string? Issuer,
    DateTimeOffset? ExpiresAt,
    string? ApiKeyPrefix);

public static AuthDecision Decide(InboundToken token, DateTimeOffset utc) => token switch
{
    { Scheme: "LTI", Version: "1.3", Issuer: { Length: > 0 } issuer }
        => new AuthDecision("lti13", issuer, Roles: ["learner"]),
    { Scheme: "Bearer", ExpiresAt: DateTimeOffset exp } when exp > utc
        => new AuthDecision("oidc", token.Issuer ?? "unknown", Roles: ["user"]),
    { Scheme: "ApiKey", ApiKeyPrefix: "sk_live" }
        => new AuthDecision("api-key", "legacy", Roles: ["service"]),
    { Scheme: "Bearer" }
        => throw new InvalidOperationException("Bearer token expired or missing exp."),
    _ => throw new InvalidOperationException($"Unsupported token {token.Scheme}.")
};

public sealed record AuthDecision(string Provider, string Subject, string[] Roles);

public static bool IsLti13(InboundToken token) => token is
{
    Scheme: "LTI",
    Version: { } version,
    Issuer: { Length: > 0 }
} && version.StartsWith("1.3", StringComparison.Ordinal);
